-- 从 专家信息一览表_含机构全称.xls 生成
-- 仅初始化 institutions + user_accounts(REVIEWER)
START TRANSACTION;

-- 1) institutions（来自 const_init 的唯一匹配）
ON DUPLICATE KEY UPDATE
name = VALUES(name),
region = VALUES(region),
city = VALUES(city),
level = VALUES(level);

-- 2) user_accounts（评审专家）
ON DUPLICATE KEY UPDATE
name = VALUES(name),
title = VALUES(title),
role = 'REVIEWER',
institution_id = VALUES(institution_id),
expert_background = VALUES(expert_background),
enabled = VALUES(enabled);

COMMIT;

-- summary: institutions=45, reviewers=97, skipped=8